import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import {
  LANDING_CTA, LCD_ROWS, LCD_WIDTH, MARQUEE_GAP, MAX_MINUTES_SHOWN, OUT_OF_SERVICE, landing, landingMinutes,
  landingPageCount, marqueeWindow, type LandingInput,
} from "./landingPreview";

/**
 * The console's landing preview against the contract corpus — `src/contracts/device-protocol/display/`,
 * generated by `gen_cases.py`, the reference implementation the Mega's `courtlogic` is checked against
 * too. Executed equals declared: the manifest's counts for `landing` and `marquee` must equal what this
 * suite ran, so a vector added to the generator turns this red until the preview renders it.
 */

const CORPUS = resolve(__dirname, "../../../contracts/device-protocol/display");
const load = <T,>(file: string): T => JSON.parse(readFileSync(join(CORPUS, file), "utf8")) as T;

type Manifest = { read_by: string[]; case_count: Record<string, number> };
type LandingCase = { id: string; input: LandingInput; rows: string[] };
type MarqueeCase = { id: string; text: string; width: number; offset: number; window: string };
type Cases = {
  constants: { width: Record<string, number>; rows: Record<string, number>; cta: Record<string, string>;
    gap: string; out_of_service: string; max_minutes_shown: number };
  landing: LandingCase[];
  marquee: MarqueeCase[];
};

const manifest = load<Manifest>("manifest.json");
const cases = load<Cases>("cases.json");
const executed: Record<string, number> = { landing: 0, marquee: 0 };

describe("display corpus — landing", () => {
  it.each(cases.landing.map((c) => [c.id, c] as const))("%s", (_id, c) => {
    expect(landing(c.input)).toEqual(c.rows);
    executed.landing += 1;
  });
});

describe("display corpus — marquee", () => {
  it.each(cases.marquee.map((c) => [c.id, c] as const))("%s", (_id, c) => {
    expect(marqueeWindow(c.text, c.width, c.offset)).toBe(c.window);
    executed.marquee += 1;
  });
});

describe("display corpus — the preview is one of the corpus's declared readers", () => {
  it("names vitest as a reader, and its constants are the preview's", () => {
    expect(manifest.read_by).toContain("vitest");
    expect(cases.constants.width).toEqual(LCD_WIDTH);
    expect(cases.constants.rows).toEqual(LCD_ROWS);
    expect(cases.constants.cta).toEqual(LANDING_CTA);
    expect(cases.constants.gap).toBe(MARQUEE_GAP);
    expect(cases.constants.out_of_service).toBe(OUT_OF_SERVICE);
    expect(cases.constants.max_minutes_shown).toBe(MAX_MINUTES_SHOWN);
  });

  it("never shows 0 MIN on a closed relay, and caps the figure", () => {
    expect(landingMinutes(1)).toBe(1);
    expect(landingMinutes(60)).toBe(1);
    expect(landingMinutes(61)).toBe(2);
    expect(landingMinutes(10_000_000)).toBe(MAX_MINUTES_SHOWN);
  });

  it("counts the pages the preview turns through", () => {
    expect(landingPageCount("expanded", true, 4)).toBe(2);
    expect(landingPageCount("expanded", false, 2)).toBe(1);
    expect(landingPageCount("compact", true, 4)).toBe(1);
    expect(landingPageCount("compact", false, 4)).toBe(5);
  });
});

afterAll(() => {
  // Executed == declared. A thrown expectation inside afterAll fails the file.
  expect(executed).toEqual({ landing: manifest.case_count.landing, marquee: manifest.case_count.marquee });
  expect(manifest.case_count.landing).toBeGreaterThanOrEqual(19);
  expect(manifest.case_count.marquee).toBeGreaterThanOrEqual(8);
});
